/*
This program draws Fig. 145 and Fig. 148 in Fricke and Klein's book

    "Vorlesungen uber die Theorie der automorphen Funktionen,
     Teubner Leipzig, Germany, 1897."

Controls:

1. Use mouse to pan
2. Press W/S to zoom in/out


Also, if you comment out the line '#define apollonian', it will show
figure 7.4 of the apollonian circle packing in the book "Indra's pearls".

*/

//try comment out the line below!
//#define apollonian


// distance between y=0 and the middle small circle (z3, r3)

#define PI 3.141592653589793
#define MAX_ITER 1000
#define CURVE_THICKNESS 0.007
#define AA 3
#define L2(x)  dot(x, x)


// middle small circle
const float r3 = 0.3;

#ifdef apollonian
    const float r2 = 4.0 * r3;
    const float r4 = 4.0 * r3;
#else
    const float r2 = 0.8;
    const float r4 = 0.8;
#endif

const float radii[3] = float[3] (r2, r3, r4);
const vec3 COLOR1 = vec3(0.85, 0.85, 0.1);
const vec3 COLOR2 = vec3(0.75, 0.5, 0.1);
const vec3 COLOR3 = vec3(0.7, 0.6, 0.85);
const vec3 COLOR4 = vec3(0.3, 0.4, 0.6);

float spacing, zoom;

vec2 getTouchPoint(vec2 z1, float r1, vec2 z2) {
    vec2 d = z2 - z1;
    d /= length(d);
    return d * r1 + z1;
}

float cross2d(vec2 A, vec2 B, vec2 C) {
    vec2 AB = B - A;
    vec2 AC = C - A;
    return AB.x * AC.y - AB.y * AC.x;
}

vec2 invert(vec2 z, vec2 cen, float r, inout float scale) {
    float k = (r * r) / dot(z - cen, z - cen);
    scale *= k;
    return cen + k * (z - cen);
}

// Pixels near the center of a circle will be inverted to
// very far away and have too large scales. This causes such
// pixels to be incorrectly rendered.
// For such pixels, scale will be roughly the square of |z|,
// where z is the final location in the fundamental domain.
// so add a squared term to fix this.
bool Equal(vec2 z, vec2 a, float scale) {
    float k = 1. + length(z);
    return k * length(z - a) / (scale * zoom) < CURVE_THICKNESS;
}


float y3, x2, x4;
vec2 z2, z3, z4;
const vec2 z1 = vec2(0, -1);
vec2 u12, u14, u23, u34;
vec2 circles[3];

bool region1(vec2 z) {
    return cross2d(z, u23, u34) > 0. && 
           cross2d(z, u12, u23) > 0. &&
           cross2d(z, u34, u14) > 0.;
}

vec3 getColor(vec2 z) {
    vec2 w = z;
    int count = 0;
    vec3 color = vec3(1, 0, 0);
    float scale = 1.0;

    for (int i = 0; i < MAX_ITER; i++) {
        for (int j = 0; j < 4; j++) {
            vec2 p = vec2[4](u12, u23, u34, u14)[j];
            if (Equal(z, p, scale)) { return vec3(0); }
        }

        bool found = true;

        if (z.y > 0.) {
            z.y = -z.y;
            count++;
            found = false;
        }
        for (int j = 0; j < 3; j++) {
            if (length(z - circles[j]) < radii[j]) {
                z = invert(z, circles[j], radii[j], scale);
                count++;
                found = false;
            }
        }

        if (found) {
            if (region1(z)) {
                color = (count % 2 == 0) ? COLOR1 : COLOR2;
            } 
            else {
                color = (count % 2 == 0) ? COLOR3 : COLOR4;
            }
            break;
        }   
    }

    float d = 1e5;
    for (int j = 0; j < 3; j++) {
        float d1 = abs(length(w - circles[j]) - radii[j]) - 0.002;
        d = min(d, d1);
    }
    d = min(d, abs(w.y) - 0.002);
    d = smoothstep(0., 0.003, d);
    color = mix(vec3(1.0), color, d);
    return color;
}

void init() {
    zoom = textureLod(iChannel0, vec2(10.5,10.5)/iResolution.xy, 0.0).x;
#ifdef apollonian
    spacing = 0.0;
    zoom *= 1.6;
#else
    spacing = (1. + sin(iTime * 1.5)) / 20.;
#endif

    y3 = -(spacing + r3);
    z3 = vec2(0., y3);
    x2 = -sqrt((r2+r3)*(r2+r3) - (r2+y3)*(r2+y3));
    z2 = vec2(x2, -r2);
    x4 = sqrt((r4+r3)*(r4+r3) - (r4+y3)*(r4+y3));
    z4 = vec2(x4, -r4);
    u12 = vec2(z2.x, 0.);
    u14 = vec2(z4.x, 0.);
    u23 = getTouchPoint(z2, r2, z3);
    u34 = getTouchPoint(z3, r3, z4);
    circles = vec2[3] (z2, z3, z4);
}


void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    init();
    vec4 pan_vals = textureLod(iChannel0, vec2(0.0,0.0),0.0);
    vec3 col = vec3(0);
    for(int ii=0; ii<AA; ii++) {
    for(int jj=0; jj<AA; jj++) {
        vec2 o = vec2(float(ii), float(jj)) / float(AA);
        vec2 uv = (2. * (fragCoord  + o) -iResolution.xy - pan_vals.xy * pow(zoom, -1.0)) / iResolution.y;
        uv *= 0.8;
        uv *= zoom;
        col += getColor(uv);
    }
    }
    col /= (float(AA) * float(AA));
    fragColor = vec4(col, 1.0);
}

// https://www.shadertoy.com/view/ldyGzW
const int Key_A = 65; const int Key_B = 66; const int Key_C = 67; const int Key_D = 68; const int Key_E = 69;
const int Key_F = 70; const int Key_G = 71; const int Key_H = 72; const int Key_I = 73; const int Key_J = 74;
const int Key_K = 75; const int Key_L = 76; const int Key_M = 77; const int Key_N = 78; const int Key_O = 79;
const int Key_P = 80; const int Key_Q = 81; const int Key_R = 82; const int Key_S = 83; const int Key_T = 84;
const int Key_U = 85; const int Key_V = 86; const int Key_W = 87; const int Key_X = 88; const int Key_Y = 89;
const int Key_Z = 90;
const int Key_0 = 48; const int Key_1 = 49; const int Key_2 = 50; const int Key_3 = 51; const int Key_4 = 52;
const int Key_5 = 53; const int Key_6 = 54; const int Key_7 = 55; const int Key_8 = 56; const int Key_9 = 57;
const int Key_Space = 32;

float ReadKeyInternal( int key, bool toggle )
{
	return textureLod( iChannel1, vec2( (float(key)+.5)/256.0, toggle?.75:.25 ), 0.0 ).x;
}

float ReadKey( int key )
{
	return ReadKeyInternal(key,false);
}

float ReadKeyToggle( int key )
{
	return ReadKeyInternal(key,true);
}



//Storage Code For Pan and Zoom


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    fragColor = vec4(0.0,0.0,0.0,1.0);
    //Only run once each frame

        if (ivec2(fragCoord.xy) == ivec2(0,0) )
        {
            //Mouse Pan Stored In Here


            vec4 prev_info = textureLod(iChannel0, vec2(0.0,0.0),0.0);
            float Zoom = textureLod(iChannel0, vec2(10.5,10.5)/iResolution.xy,0.0).x;
            float prev_pan_x = prev_info.x;
            float prev_pan_y = prev_info.y;

            float legacy_pan_x = prev_info.z;
            float legacy_pan_y = prev_info.w;

            float pan_x = (iMouse.x - abs(iMouse.z))*Zoom + legacy_pan_x;
            float pan_y = (iMouse.y - abs(iMouse.w))*Zoom + legacy_pan_y;

            if (iMouse.z < 0.0)
            {
                //Mouse has been lifted up
                legacy_pan_x = prev_pan_x;
                legacy_pan_y = prev_pan_y;
                pan_x = legacy_pan_x;
                pan_y = legacy_pan_y;

            }     

            fragColor = vec4(pan_x, pan_y, legacy_pan_x, legacy_pan_y);
        }

    //Zoom settings
    if (ivec2(fragCoord.xy) == ivec2(10,10) )
    {

        float x = textureLod(iChannel0, vec2(10.5,10.5)/iResolution.xy,0.0).y;
        //Number of times zoom in - zoom out has happend

        x += ReadKey(Key_W)-ReadKey(Key_S);

        float Zoom = pow(2.71, -x*0.05); //Times all limits by this value

        fragColor = vec4(Zoom, x,0.0,0.0);
    }


}
